// /hotels hub: filter bar that shows one city's categories or all of them.
// Every link is already in the HTML (so crawlers and no-JS visitors see everything);
// this just toggles visibility. Generated by scripts/stays/build_hotels_hub.py.
const bar = document.querySelector('.stays-hub-filter');
if (bar) {
  const cities = document.querySelectorAll('.stays-hub-city');
  bar.addEventListener('click', (e) => {
    const btn = e.target.closest('.stays-hub-tab');
    if (!btn) return;
    bar.querySelectorAll('.stays-hub-tab').forEach((b) => b.classList.toggle('is-active', b === btn));
    const city = btn.dataset.city;
    cities.forEach((sec) => { sec.hidden = city !== 'all' && sec.dataset.city !== city; });
  });
}
